arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_2013_06.json', 'r') as f:
    data = json.load(f)

# Print keys at top level
def print_structure(d, indent=0):
    if isinstance(d, dict):
        for k, v in d.items():
            print(' ' * indent + str(k))
            if indent < 2:
                print_structure(v, indent + 2)
    elif isinstance(d, list) and len(d) > 0:
        print(' ' * indent + f'List with {len(d)} items')
        if indent < 2:
            print_structure(d[0], indent + 2)

print_structure(data)
"
